// Meta-tests for the game-validation machinery: it must PASS correct records and FAIL wrong ones.
// All fixtures here are SYNTHETIC (generated by the engine) and exist only in memory / temp dirs;
// they never go into fixtures/real-game.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { GRADES, initialState, makeContext, simulate } from '../engine/shellout.mjs';
import { evaluateFixture, evaluateGate, parseFixture } from '../validation/game-fixture.mjs';

const hex = s => s.map(v => '0x' + v.toString(16).padStart(8, '0'));
const colors = pulls => pulls.map(p => GRADES[p.grade]);
const flip = (arr, i) => arr.map((c, k) => (k === i ? (c === 'blue' ? 'purple' : 'blue') : c));

/** Synthetic direct-mode fixture: `before` pulls into a stream, then `n` recorded pulls. */
function direct({ key = 'synthetic00000000001', mode = 'normal', season = 17, own = [2, 2], before = 500, n = 30 } = {}) {
  const ctx = makeContext({ season, missingBanners: own[0], missingTitles: own[1] });
  const h = simulate(initialState(key, mode), ctx, before);
  const rec = simulate(h.state, h.ctx, n);
  return {
    fixture: {
      source: 'real-game', mode, season,
      ownershipBeforeFirstPull: { missingBanners: h.ctx.missingBanners, missingTitles: h.ctx.missingTitles },
      startStateBeforeFirstPull: hex(h.state), pulls: colors(rec.pulls),
    },
    rec, h,
  };
}

/** Locate a pull index with the requested jackpot event in a long simulated stream. */
function findEvent(kind, key, own) {
  const ctx = makeContext({ season: 17, missingBanners: own, missingTitles: own });
  const run = simulate(initialState(key, 'normal'), ctx, 60000);
  const j = run.pulls.findIndex((p, k) => k > 50 && (kind === 'awarded' ? p.row.subType === 'Limited' && !p.substituted : p.substituted));
  assert.ok(j > 0, `no ${kind} event found`);
  return { j, ctx };
}
function eventFixture(kind, { lead = 5, tail = 15 } = {}) {
  const key = kind === 'awarded' ? 'jackpotaward00000001' : 'jackpotsubst00000001';
  const own = kind === 'awarded' ? 2 : 0;
  const { j } = findEvent(kind, key, own);
  return direct({ key, own: [own, own], before: j - lead, n: lead + 1 + tail });
}

// ---------- direct reproduction (startStateBeforeFirstPull) ----------
test('direct mode: correct record passes WITHOUT any position search', () => {
  const { fixture } = direct();
  const r = evaluateFixture(fixture);
  assert.equal(r.ok, true, r.errors.join());
  assert.equal(r.anchor, 'startStateBeforeFirstPull');
  assert.equal(r.offsetsSearched, 0);
  assert.equal(r.heldOutStart, 0);
  assert.equal(r.heldOutCount, 30);
});

test('direct mode: any single wrong pull fails and names the pull', () => {
  const { fixture } = direct();
  for (const i of [0, 14, 29]) {
    const r = evaluateFixture({ ...fixture, pulls: flip(fixture.pulls, i) });
    assert.equal(r.ok, false);
    assert.match(r.errors.join(), new RegExp(`pull ${i}:`));
  }
});

test('direct mode: an ID-derived initialState mislabeled as startStateBeforeFirstPull fails (no silent search)', () => {
  const { fixture } = direct({ before: 800 });
  const wrong = { ...fixture, startStateBeforeFirstPull: hex(initialState('synthetic00000000001', 'normal')) };
  assert.equal(evaluateFixture(wrong).ok, false);
});

test('direct mode: too few pulls to count as held-out fails', () => {
  const { fixture } = direct({ n: 9 });
  assert.equal(evaluateFixture(fixture).ok, false);
});

test('currentStateAfterLastPull: matching state passes, wrong state fails', () => {
  const { fixture, rec } = direct();
  assert.equal(evaluateFixture({ ...fixture, currentStateAfterLastPull: hex(rec.state) }).ok, true);
  const bad = [...rec.state]; bad[3] = (bad[3] ^ 1) >>> 0;
  const r = evaluateFixture({ ...fixture, currentStateAfterLastPull: hex(bad) });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(), /currentStateAfterLastPull/);
});

// ---------- search mode (ID / initialState) ----------
test('search mode: position found from initialState, then unseen pulls must match', () => {
  const key = 'searchmode0000000001';
  const ctx = makeContext({ season: 17 });
  const h = simulate(initialState(key, 'fest'), ctx, 700);
  const rec = simulate(h.state, h.ctx, 34);
  const base = { source: 'real-game', mode: 'fest', season: 17, ownershipBeforeFirstPull: { missingBanners: h.ctx.missingBanners, missingTitles: h.ctx.missingTitles }, initialState: hex(initialState(key, 'fest')), pulls: colors(rec.pulls), useForSearch: 22, maxOffset: 1 << 18 };
  const ok = evaluateFixture(base);
  assert.equal(ok.ok, true, ok.errors.join());
  assert.equal(ok.heldOutStart, 22); assert.equal(ok.heldOutCount, 12);
  assert.ok(ok.offsetsSearched > 0);
  assert.deepEqual(ok.stateBeforeFirstPull, h.state);
  // wrong unseen pull -> fail
  assert.equal(evaluateFixture({ ...base, pulls: flip(base.pulls, 30) }).ok, false);
  // wrong pull inside the search window -> no position -> fail
  assert.equal(evaluateFixture({ ...base, pulls: flip(base.pulls, 3) }).ok, false);
  // too few unseen pulls -> fail even if everything matches
  assert.equal(evaluateFixture({ ...base, useForSearch: 25 }).ok, false);
  // too few pulls to make the position unique -> fail (no prediction made)
  const r = evaluateFixture({ ...base, useForSearch: 3 });
  assert.equal(r.ok, false); assert.match(r.errors.join(), /not unique/);
});

test('search mode via nplnUserId equals search via its initialState', () => {
  const key = 'searchmode0000000003';
  const ctx = makeContext({ season: 17 });
  const h = simulate(initialState(key, 'normal'), ctx, 300);
  const rec = simulate(h.state, h.ctx, 32);
  const r = evaluateFixture({ source: 'real-game', mode: 'normal', season: 17, ownershipBeforeFirstPull: { missingBanners: h.ctx.missingBanners, missingTitles: h.ctx.missingTitles }, nplnUserId: key, pulls: colors(rec.pulls), maxOffset: 1 << 16 });
  assert.equal(r.ok, true, r.errors.join());
});

test('KNOWN LIMITATION: phase-shift twin positions are reported as "not unique" (conservative failure)', () => {
  // Offset t+1 can also match when the first pull at t draws 2 u32 and the shifted reading lands on a
  // zero-extra-draw row of the same color: both paths then share every later state. The search currently
  // counts them as 2 positions, so the gate FAILS rather than passing on an ambiguous position.
  const key = 'searchmode0000000002';
  const ctx = makeContext({ season: 17 });
  const h = simulate(initialState(key, 'normal'), ctx, 300);
  const rec = simulate(h.state, h.ctx, 32);
  const r = evaluateFixture({ source: 'real-game', mode: 'normal', season: 17, ownershipBeforeFirstPull: { missingBanners: h.ctx.missingBanners, missingTitles: h.ctx.missingTitles }, nplnUserId: key, pulls: colors(rec.pulls), maxOffset: 1 << 16 });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(), /not unique/);
});

// ---------- schema: the three states are never ambiguous ----------
test('schema: exactly one state anchor, no search options with a direct state, real-game source only', () => {
  const { fixture } = direct();
  assert.throws(() => parseFixture({ ...fixture, nplnUserId: 'abcdefabcdef' }), /exactly one/);
  assert.throws(() => parseFixture({ ...fixture, initialState: fixture.startStateBeforeFirstPull }), /exactly one/);
  const none = { ...fixture }; delete none.startStateBeforeFirstPull;
  assert.throws(() => parseFixture(none), /exactly one/);
  assert.throws(() => parseFixture({ ...fixture, useForSearch: 20 }), /not allowed/);
  assert.throws(() => parseFixture({ ...fixture, source: 'synthetic' }), /real-game/);
  assert.throws(() => parseFixture({ ...fixture, ownershipBeforeFirstPull: undefined }), /ownership/);
  assert.equal(evaluateFixture({ ...fixture, source: 'synthetic' }).ok, false);
});

// ---------- jackpot rules: strict event verification ----------
test('jackpot award: verified only with tail >= 10 and every competing draw rule contradicted', () => {
  const { fixture } = eventFixture('awarded');
  const r = evaluateFixture(fixture);
  assert.equal(r.ok, true, r.errors.join());
  const ev = r.events.find(e => e.kind === 'awarded');
  assert.ok(ev && ev.verified, JSON.stringify(r.events));
  assert.equal(r.events.find(e => e.kind === 'awarded').index, 5);

  const short = eventFixture('awarded', { lead: 10, tail: 4 }).fixture;
  const rs = evaluateFixture(short);
  assert.equal(rs.ok, true);
  assert.equal(rs.events.find(e => e.kind === 'awarded').verified, false, 'short tail must not verify the rule');
});

test('jackpot award: wrong ownership input fails the record', () => {
  const { fixture } = eventFixture('awarded');
  const wrong = { ...fixture, ownershipBeforeFirstPull: { missingBanners: 0, missingTitles: 0 } };
  assert.equal(evaluateFixture(wrong).ok, false);
});

test('jackpot substitution: verified with tail; wrong ownership fails', () => {
  const { fixture } = eventFixture('substituted');
  const r = evaluateFixture(fixture);
  assert.equal(r.ok, true, r.errors.join());
  assert.ok(r.events.some(e => e.kind === 'substituted' && e.verified), JSON.stringify(r.events));
  const wrong = { ...fixture, ownershipBeforeFirstPull: { missingBanners: 2, missingTitles: 2 } };
  assert.equal(evaluateFixture(wrong).ok, false);
});

test('a record with no gold/silver/substitution verifies no jackpot rule', () => {
  let d, k = 0;
  do { d = direct({ before: 100 + k++ * 37, n: 30 }); } while (d.rec.pulls.some(p => p.row.subType === 'Limited' || p.substituted));
  const r = evaluateFixture(d.fixture);
  assert.equal(r.ok, true);
  assert.equal(r.events.length, 0);
});

test('jackpotPullIndices annotation must equal engine-predicted awards', () => {
  const { fixture } = eventFixture('awarded');
  assert.equal(evaluateFixture({ ...fixture, jackpotPullIndices: [5] }).ok, true);
  assert.equal(evaluateFixture({ ...fixture, jackpotPullIndices: [6] }).ok, false);
  assert.equal(evaluateFixture({ ...fixture, jackpotPullIndices: [] }).ok, false);
});

// ---------- gate ----------
test('gate: fails with no fixtures, with incomplete coverage, and passes only with full coverage', () => {
  assert.equal(evaluateGate([]).ok, false);
  const normal = direct().fixture;
  const fest = direct({ key: 'festsynthetic0000001', mode: 'fest' }).fixture;
  const award = eventFixture('awarded').fixture;
  const subst = eventFixture('substituted').fixture;
  const g1 = evaluateGate([{ name: 'n', data: normal }, { name: 'f', data: fest }]);
  assert.equal(g1.ok, false);
  assert.deepEqual(g1.coverage, { normalStreamHeldOut: true, festStreamHeldOut: true, jackpotAwardedVerified: false, jackpotSubstitutionVerified: false });
  const all = [normal, fest, award, subst].map((data, i) => ({ name: `f${i}`, data }));
  assert.equal(evaluateGate(all).ok, true, evaluateGate(all).problems.join('\n'));
  // one broken record breaks the whole gate
  all[1] = { name: 'bad', data: { ...fest, pulls: flip(fest.pulls, 20) } };
  assert.equal(evaluateGate(all).ok, false);
});

test('gate CLI exits non-zero for the repository (no real records yet) and for an empty dir', () => {
  const run = dir => { try { execFileSync(process.execPath, ['validation/run-game-validation.mjs', dir], { stdio: 'pipe' }); return 0; } catch (e) { return e.status; } };
  assert.equal(run('fixtures/real-game'), 1);
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gate-'));
  assert.equal(run(tmp), 1);
});
